880e80e8-f303-43c3-bf69-8462b94678f4	chief-strategist	Chief Strategist Agent	Creates a "first-principles" Build Plan (e.g., AIDA, PAS) from a simple objective.	data-driven	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return parsed plan"}, "parse_plan": {"action": "parse_json_field", "config": {"source_field": "build_plan_raw"}, "next_step": "complete", "description": "Parse JSON from LLM response using existing datahelpers", "output_field": "plan_data"}, "generate_build_plan": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "max_tokens": 8192, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_data": ["domain", "objective", "model"], "prompt_template": "You are a Site Planner designing the structure for {{.input_data.domain}}.\\n\\nOBJECTIVE: {{.input_data.objective}}\\nMARKETING MODEL: {{.input_data.model}}\\n\\nSTEP 1: Determine the best site type for this objective.\\n\\nSite Type Guidelines:\\n\\nLANDING (1 page, 5-8 components)\\n- Product launches, lead generation, focused campaigns\\n- Single conversion goal, minimal navigation\\n- Revenue: Direct sales, lead capture\\n\\nCORPORATE (4-6 pages)\\n- Professional services, consulting, established businesses\\n- Trust-building, multiple service areas\\n- Revenue: Service contracts, B2B relationships\\n\\nPORTFOLIO (3-5 pages)\\n- Creatives, agencies, freelancers\\n- Case study focused, visual showcase\\n- Revenue: Project work, client acquisition\\n\\nECOMMERCE (2-4 pages + product structure)\\n- Product sales, shopping focused\\n- Category browsing, cart functionality\\n- Revenue: Direct product sales\\n\\nCONTENT (4-8 pages + article structure)\\n- News sites, blogs, recipes, celebrity gossip, lifestyle\\n- Content-driven traffic, regular publishing\\n- SEO focused, high page count potential\\n- Revenue: Advertising, affiliate links, sponsored content\\n\\nTOOLS (2-5 pages + tool interfaces)\\n- Calculators (mortgage, tiles, BMI, etc.), converters, utilities\\n- Feature/functionality driven, practical value\\n- User retention through bookmarking\\n- Revenue: Advertising, affiliate referrals, premium features\\n\\nSTEP 2: Plan each page with specific components.\\n\\nAvailable component types:\\n- hero-centered, hero-split, hero-video\\n- services-grid, services-list\\n- features-cards, features-comparison\\n- testimonials-carousel, testimonials-grid\\n- team-grid, pricing-tiers, faq-accordion\\n- cta-banner, cta-split\\n- contact-form, contact-simple\\n- about-story, about-values\\n- footer-standard\\n- blog-grid, blog-featured, article-layout\\n- recipe-card, recipe-grid, recipe-detail\\n- tool-calculator, tool-converter, tool-interface\\n- ad-banner, ad-sidebar, affiliate-showcase\\n- category-grid, content-feed, search-bar\\n- social-share, comments-section, newsletter-signup\\n\\nSTEP 3: Create the sitemap with navigation structure.\\n\\nThe sitemap defines:\\n- How each page appears in navigation\\n- The URL for each page\\n- Whether it appears in header nav, footer nav, or both\\n\\nURL Rules:\\n- Home page: /index.html\\n- Other pages: /{page-name}.html (e.g., /about.html, /services.html)\\n- Use lowercase, hyphens for multi-word names\\n\\nOUTPUT FORMAT (valid JSON only):\\n{\\n  \\"site_type\\": \\"landing|corporate|portfolio|ecommerce|content|tools\\",\\n  \\"reasoning\\": \\"Why this structure fits the objective\\",\\n  \\"theme_suggestion\\": \\"professional|bold|minimal|creative|editorial|functional\\",\\n  \\"revenue_model\\": \\"direct_sales|services|advertising|affiliate|freemium\\",\\n  \\"pages\\": [\\n    {\\n      \\"name\\": \\"index\\",\\n      \\"title\\": \\"Page Title | Brand\\",\\n      \\"purpose\\": \\"What this page achieves\\",\\n      \\"components\\": [\\n        {\\"type\\": \\"hero-centered\\", \\"priority\\": \\"high\\"},\\n        {\\"type\\": \\"services-grid\\", \\"priority\\": \\"high\\"}\\n      ],\\n      \\"meta_description\\": \\"SEO description\\"\\n    }\\n  ],\\n  \\"sitemap\\": [\\n    {\\"label\\": \\"Home\\", \\"page\\": \\"index\\", \\"url\\": \\"/index.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"About\\", \\"page\\": \\"about\\", \\"url\\": \\"/about.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Services\\", \\"page\\": \\"services\\", \\"url\\": \\"/services.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Contact\\", \\"page\\": \\"contact\\", \\"url\\": \\"/contact.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Privacy Policy\\", \\"page\\": \\"privacy\\", \\"url\\": \\"/privacy.html\\", \\"in_header\\": false, \\"in_footer\\": true}\\n  ],\\n  \\"global\\": {\\n    \\"brand_tone\\": \\"professional|friendly|bold|technical|editorial|practical\\",\\n    \\"primary_cta\\": {\\"text\\": \\"Get Started\\", \\"url\\": \\"/contact.html\\"}\\n  }\\n}\\n\\nIMPORTANT:\\n- Every page in \\"pages\\" array MUST have a corresponding entry in \\"sitemap\\"\\n- The \\"page\\" field in sitemap MUST match the \\"name\\" field in pages\\n- Home page is always /index.html\\n- Include privacy/terms pages in footer only (in_header: false)\\n\\nEXAMPLE - Corporate site:\\n{\\n  \\"site_type\\": \\"corporate\\",\\n  \\"pages\\": [\\n    {\\"name\\": \\"index\\", \\"title\\": \\"Home | Acme Corp\\", \\"components\\": [{\\"type\\": \\"hero-centered\\"}, {\\"type\\": \\"services-grid\\"}, {\\"type\\": \\"testimonials-carousel\\"}, {\\"type\\": \\"cta-banner\\"}]},\\n    {\\"name\\": \\"about\\", \\"title\\": \\"About Us | Acme Corp\\", \\"components\\": [{\\"type\\": \\"about-story\\"}, {\\"type\\": \\"team-grid\\"}, {\\"type\\": \\"about-values\\"}]},\\n    {\\"name\\": \\"services\\", \\"title\\": \\"Our Services | Acme Corp\\", \\"components\\": [{\\"type\\": \\"hero-split\\"}, {\\"type\\": \\"services-list\\"}, {\\"type\\": \\"faq-accordion\\"}]},\\n    {\\"name\\": \\"contact\\", \\"title\\": \\"Contact Us | Acme Corp\\", \\"components\\": [{\\"type\\": \\"contact-form\\"}, {\\"type\\": \\"cta-split\\"}]}\\n  ],\\n  \\"sitemap\\": [\\n    {\\"label\\": \\"Home\\", \\"page\\": \\"index\\", \\"url\\": \\"/index.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"About Us\\", \\"page\\": \\"about\\", \\"url\\": \\"/about.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Services\\", \\"page\\": \\"services\\", \\"url\\": \\"/services.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Contact\\", \\"page\\": \\"contact\\", \\"url\\": \\"/contact.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Privacy Policy\\", \\"page\\": \\"privacy\\", \\"url\\": \\"/privacy.html\\", \\"in_header\\": false, \\"in_footer\\": true}\\n  ],\\n  \\"global\\": {\\n    \\"brand_tone\\": \\"professional\\",\\n    \\"primary_cta\\": {\\"text\\": \\"Get in Touch\\", \\"url\\": \\"/contact.html\\"}\\n  }\\n}"}, "next_step": "parse_plan", "description": "Create the Build Plan using LLM", "output_field": "build_plan_raw"}}, "start_step": "generate_build_plan"}, "processing_mode": "task", "timeout_seconds": 120}	t	2025-11-15 18:27:24.625309+00	2026-02-23 19:23:31.791914+00	\N	["strategy", "llm", "planning"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "1Gi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	strategist	active	["website"]	{}	0	f	\N	\N
6f40f1f5-34d1-4892-b78b-f08e042f4898	briefing-agent	Briefing Agent	Executes briefing questionnaires - either via LLM inference or HITL collection	data-collection	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return the completed brief"}, "check_mode": {"action": "evaluate_condition", "config": {"default": "infer_via_llm", "conditions": {"auto": "infer_via_llm", "interactive": "collect_via_hitl"}, "condition_field": "input_data.hitl_mode"}, "next_step": "infer_via_llm", "description": "Determine if briefing should be interactive or auto-inferred"}, "infer_via_llm": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "max_tokens": 4000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["input_data", "questionnaire"], "output_field": "brief_answers", "prompt_template": "You are completing a briefing questionnaire for a website project.\\n\\nProject Info:\\n- Domain: {{.input_data.domain}}\\n- Objective: {{.input_data.objective}}\\n- Site Type: {{.input_data.site_type}}\\n- Industry: {{.input_data.detected_industry}}\\n\\nQuestionnaire to complete:\\n{{.questionnaire}}\\n\\nBased on the domain name, objective, and your knowledge of the industry, provide thoughtful answers to each question in the questionnaire.\\n\\nFor questions you cannot confidently answer from the available information, provide reasonable defaults appropriate for the industry.\\n\\nReturn your answers as a JSON object where keys match the field names in the questionnaire:\\n{\\n  \\"field_name_1\\": \\"your answer\\",\\n  \\"field_name_2\\": \\"your answer\\",\\n  ...\\n}\\n\\nReturn ONLY valid JSON."}, "next_step": "complete"}, "collect_via_hitl": {"action": "request_human_input", "config": {"message": "Please complete the briefing questionnaire for this project", "request_type": "questionnaire", "timeout_seconds": 86400, "questionnaire_field": "questionnaire"}, "next_step": "complete", "description": "Collect answers via human-in-the-loop", "output_field": "brief_answers"}}, "start_step": "check_mode"}, "processing_mode": "task", "timeout_seconds": 120}	t	2025-11-28 09:55:45.098946+00	2026-02-23 19:23:31.791914+00	\N	["briefing", "questionnaire", "llm", "hitl"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	experimental	[]	{}	0	f	\N	\N
