69606f76-99d9-4f16-a8d2-7a8eee735bad	domain-analyst	Domain Analyst	Analyzes domains and determines appropriate website type	data-driven	{"workflow": {"steps": {"analyze": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "output_type": "json", "input_fields": ["input_data"], "prompt_template": "You are a domain analyst. Analyze this website project:\\n\\nDomain: {{.input_data.domain}}\\nObjective: {{.input_data.objective}}\\nPersuasion Model: {{.input_data.model}}\\n\\nProvide a JSON analysis with:\\n- target_audience: who this site is for\\n- key_value_propositions: array of main benefits to highlight\\n- tone: recommended writing tone\\n- competitive_advantages: array of what makes this unique\\n- recommended_sections: array of suggested page sections\\n- industry: detected industry vertical\\n- keywords: array of SEO keywords\\n\\nReturn ONLY valid JSON, no markdown or explanation."}, "next_step": "complete", "description": "Analyze domain and business requirements", "output_field": "analysis_result"}, "complete": {"action": "complete_workflow", "description": "Return domain analysis"}}, "start_step": "analyze"}}	t	2025-08-10 16:00:36.520323+00	2026-02-23 19:23:31.791914+00	\N	["analysis", "categorization", "domain-research", "domain-validation", "business-categorization", "keyword-extraction"]	docker.io/aqls/agent-chassis	v1.0.803	{./agent-chassis,-config,configs/agent-chassis.yaml}	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"dlq": "system.agent.domain-analyst.dlq", "errors": "system.agent.domain-analyst.errors", "requests": "system.agent.domain-analyst.requests", "responses": "system.agent.domain-analyst.responses"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	1	\N	{"steps": {"analyze": {"action": "execute_llm_prompt", "config": {"prompt_template": "