c16638a7-c867-481e-a71e-6ae751ac961b	site-strategist	Site Strategist	Creates strategic build plans using behavioral psychology and briefing data. Works with intake orchestrator flow.	strategy	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return the Build Plan"}, "generate_build_plan": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "max_tokens": 10000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["input_data", "brief_data"], "output_field": "build_plan_json", "prompt_template": "You are an english website strategist creating a Build Plan based on behavioural psychology.\\n\\nWebsite Request:\\n- Domain: {{.input_data.domain}}\\n- Objective: {{.input_data.objective}}\\n- Model: {{.input_data.model}}\\n\\n{{if .brief_data}}Brief Data:\\n{{.brief_data}}\\n{{end}}\\n\\nBehavioural Models:\\n- AIDA: Attention → Interest → Desire → (Conviction) -> Action\\n- PAS: Problem → Agitate → Solution\\n- FAB: Features → Advantages → Benefits\\n- 4Ps: Promise → Picture → Proof → Push\\n\\nAvailable Components: header, hero, features, social_proof, pricing, faq, call_to_action, footer\\n\\nCreate a build plan that maps the behavioural model to sections with specific guidance.\\n\\nReturn ONLY valid JSON:\\n{\\n  \\"model\\": \\"AIDA\\",\\n  \\"sections\\": [\\"header\\", \\"hero\\", \\"features\\", \\"social_proof\\", \\"pricing\\", \\"faq\\", \\"call_to_action\\", \\"footer\\"],\\n  \\"section_guidance\\": {\\n    \\"hero\\": {\\n      \\"stage\\": \\"Attention\\",\\n      \\"purpose\\": \\"Grab attention with bold value proposition\\",\\n      \\"key_message\\": \\"Main benefit headline\\",\\n      \\"tone\\": \\"Confident, clear\\"\\n    },\\n    \\"features\\": {\\n      \\"stage\\": \\"Interest\\",\\n      \\"purpose\\": \\"Build interest with capabilities\\",\\n      \\"key_message\\": \\"What it does\\",\\n      \\"tone\\": \\"Informative\\"\\n    }\\n  },\\n  \\"theme\\": \\"tech-saas\\"\\n}\\n\\nProvide section_guidance for each section in the sections array. Keep this guidance concise. Return ONLY the JSON object."}, "next_step": "complete"}}, "start_step": "generate_build_plan"}, "processing_mode": "task", "timeout_seconds": 120}	t	2025-11-29 17:24:43.168225+00	2026-02-23 19:23:31.791914+00	\N	["strategy", "planning", "llm"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	strategist	active	["website"]	{}	0	f	\N	\N
