60195d6d-3960-41cb-9e2a-ae51a5aadeb8	site-classifier	Site Classifier	Analyzes domain and objective to determine site type and recommend appropriate builder group	classification	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return classification result"}, "classify_site": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "max_tokens": 1500, "api_key_env_var": "ANTHROPIC_API_KEY"}, "output_type": "json", "input_fields": ["input_data", "available_builders"], "output_field": "classification_result", "prompt_template": "Classify this website project and recommend the appropriate builder.\\n\\nInput:\\n- Domain: {{.domain}}\\n- Objective: {{.objective}}\\n\\nAvailable Builders:\\n{{range .available_builders.agents}}- {{.type}}: {{.description}}\\n{{end}}\\n\\nClassify the site into ONE of these types based on the objective:\\n\\n**landing** - Conversion-focused single-purpose sites:\\n- Product/service sales pages, SaaS landing pages\\n- Lead generation, signups, app downloads\\n- Event registration, clear single CTA goal\\n\\n**content** - Publishing/content sites:\\n- News, blogs, magazines, articles\\n- Content aggregation, SEO/traffic focused\\n- Category navigation, archives\\n\\n**portfolio** - Showcase/portfolio sites:\\n- Creative portfolios, agencies, case studies\\n- Visual/image heavy, project galleries\\n\\n**brochure** - Multi-page business sites:\\n- Corporate sites, general business presence\\n- Service providers, consultants, professional services\\n- About/Services/Contact structure\\n\\nReturn ONLY valid JSON with this structure:\\n{\\n  \\"site_type\\": \\"landing|content|portfolio|brochure\\",\\n  \\"confidence\\": 0.0-1.0,\\n  \\"reasoning\\": \\"brief explanation\\",\\n  \\"recommended_builder\\": \\"builder-type\\",\\n  \\"detected_industry\\": \\"industry name\\",\\n  \\"detected_signals\\": [\\"signal1\\", \\"signal2\\", ...]\\n}"}, "next_step": "complete"}}, "start_step": "classify_site"}, "processing_mode": "task", "timeout_seconds": 30}	t	2025-11-28 10:01:15.964026+00	2026-02-23 20:52:12.034694+00	\N	["classification", "analysis", "llm"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "250m", "memory": "256Mi"}, "requests": {"cpu": "50m", "memory": "128Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	experimental	[]	{}	0	f	\N	\N
