5946a27b-38ab-41e8-8b49-7bc1a4b626b8	page-content-writer	Page Content Writer	Writes content for a single page. Loads section components, renders templates with brief data, calls LLM for content sections needing original writing. Can spawn research-agent for research-backed content.	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_field": "page_content"}}, "compile_page": {"action": "compile_page_sections", "config": {"page_from": "input_data.current_page", "inject_head": true, "inject_footer": true, "inject_header": true, "sections_from": "processed_sections", "include_research_ids": true}, "next_step": "complete", "description": "Compile all sections into page output", "output_field": "page_content"}, "build_render_context": {"action": "build_render_context", "config": {"sources": {"page": "input_data.current_page", "plan": "input_data.site_plan", "site": "input_data.site_record", "brief": "input_data.reviewed_brief", "style": "input_data.style_collection", "assets": "brand_assets", "db_sync": "input_data.db_sync", "available_pages": "db_sync.pages"}, "site_id_field": "input_data.site_record.site_id"}, "next_step": "process_sections_loop", "description": "Build render context from brief, site, and brand data", "output_field": "render_context"}, "load_page_components": {"action": "load_page_section_components", "config": {"page_from": "input_data.current_page", "sections_from": "input_data.current_page.sections", "include_templates": true, "include_input_schema": true}, "next_step": "build_render_context", "description": "Load component definitions for this page's sections", "output_field": "section_components"}, "prepare_link_context": {"action": "prepare_link_context", "config": {"enabled": true, "pages_field": "db_sync.pages", "max_links_per_section": 3}, "next_step": "load_page_components", "description": "Prepare available pages context for internal linking", "output_field": "link_context"}, "spawn_research_agent": {"action": "spawn_agent", "config": {"role": "researcher", "agent_type": "research-agent", "await_response": true}, "next_step": "prepare_link_context", "description": "Spawn research agent in case sections need research", "output_field": "researcher_info"}, "process_sections_loop": {"action": "loop", "config": {"loop_var": "current_section", "iterate_over": "section_components.components", "sub_workflow": {"steps": {"render_section": {"action": "render_component", "config": {"output_html": true, "content_from": "generated_content.result", "context_from": "render_context", "component_from": "current_section"}, "description": "Render LLM-generated content into component template", "output_field": "section_output"}, "call_researcher": {"action": "call_agent", "config": {"agent_type": "research-agent", "target_role": "researcher", "input_mapping": {"site_record": "input_data.site_record", "reviewed_brief": "input_data.reviewed_brief", "current_section": "current_section"}, "timeout_seconds": 90}, "next_step": "generate_content", "description": "Research topic for this section", "output_field": "research_result"}, "generate_content": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "max_tokens": 2000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["current_section", "render_context", "reviewed_brief", "current_page", "link_context", "site_plan"], "output_format": "json", "prompt_template": "Write content for the {{.current_section.category}} section of {{.current_page.title}}.\\n\\n## Company Context\\nCompany: {{.render_context.company_name}}\\nIndustry: {{.render_context.industry}}\\nTone: {{.render_context.tone}}\\nTarget Audience: {{.render_context.target_audience}}\\nServices: {{.reviewed_brief.services}}\\nTagline: {{.render_context.tagline}}\\n\\n## Official Contact Information (USE ONLY THESE - DO NOT INVENT)\\nEmail: {{.render_context.email}}\\nPhone: {{.render_context.phone}}\\nLocation: {{.reviewed_brief.headquarters}}\\n\\n{{if .link_context.link_constraint_text}}\\n## Internal Linking\\n{{.link_context.link_constraint_text}}\\n\\n{{end}}\\n## Section Requirements\\nComponent: {{.current_section.name}}\\nFunction: {{.current_section.category}}\\nPurpose: {{.current_section.description}}\\n\\n## Data Schema Required\\n{{.current_section.input_schema}}\\n\\n{{if .research_result}}\\n## Research Findings\\n{{.research_result.response.summary}}\\n\\nSources:\\n{{range $index, $src := .research_result.response.sources}}\\n- [{{$index}}] {{$src.title}} ({{$src.domain}})\\n{{end}}\\n{{end}}\\n\\n## Task\\nWrite compelling content for this section that is relevant to the company's industry and services.\\n\\nReturn JSON with these EXACT field names (use the ones that apply to this component type):\\n\\n### For Hero/Banner sections:\\n```json\\n{\\n  \\"headline\\": \\"Your Compelling Main Headline\\",\\n  \\"subheadline\\": \\"Supporting text that expands on the headline\\",\\n  \\"primary_cta\\": \\"Get Started\\",\\n  \\"primary_cta_url\\": \\"/contact.html\\",\\n  \\"secondary_cta\\": \\"Learn More\\",\\n  \\"secondary_cta_url\\": \\"/about.html\\"\\n}\\n```\\n\\n### For Feature/Services sections:\\n```json\\n{\\n  \\"headline\\": \\"Section Headline\\",\\n  \\"subheadline\\": \\"Brief introduction\\",\\n  \\"features\\": [\\n    {\\"name\\": \\"Feature Name\\", \\"description\\": \\"Feature description\\", \\"icon\\": \\"icon-name\\"},\\n    {\\"name\\": \\"Feature 2\\", \\"description\\": \\"Description 2\\", \\"icon\\": \\"icon-name\\"}\\n  ]\\n}\\n```\\n\\n### For CTA/Call-to-Action sections:\\n```json\\n{\\n  \\"headline\\": \\"Ready to Get Started?\\",\\n  \\"subheadline\\": \\"Contact us today\\",\\n  \\"primary_cta\\": \\"Contact Us\\",\\n  \\"primary_cta_url\\": \\"/contact.html\\"\\n}\\n```\\n\\n### For Text/Content/About sections:\\n```json\\n{\\n  \\"heading\\": \\"Section Heading\\",\\n  \\"content\\": \\"<p>First paragraph of content here.</p><p>Second paragraph here.</p><p>Third paragraph if needed.</p>\\"\\n}\\n```\\n\\n### For Contact Info sections:\\n```json\\n{\\n  \\"heading\\": \\"Contact Us\\",\\n  \\"email\\": \\"USE_BRIEF_EMAIL\\",\\n  \\"phone\\": \\"USE_BRIEF_PHONE\\",\\n  \\"hours\\": \\"Monday-Friday 9am-5pm\\"\\n}\\n```\\n\\n### For Testimonial/Social Proof sections:\\nUse the company's own voice to describe their approach and values. Do NOT create fake testimonials.\\n```json\\n{\\n  \\"headline\\": \\"What We Stand For\\",\\n  \\"subheadline\\": \\"Our commitment to our clients\\",\\n  \\"testimonials\\": [\\n    {\\"quote\\": \\"A statement about the company's approach or philosophy in their own voice - NOT attributed to a fake person\\", \\"name\\": \\"\\", \\"title\\": \\"\\"},\\n    {\\"quote\\": \\"Another statement about values or working approach\\", \\"name\\": \\"\\", \\"title\\": \\"\\"}\\n  ]\\n}\\n```\\nWhen the site owner adds real testimonials later, these placeholders will be replaced.\\n\\n### For Case Study sections:\\nDescribe the types of work the company does and the outcomes they aim for. Do NOT invent specific clients, projects, or results.\\n```json\\n{\\n  \\"headline\\": \\"Our Work\\",\\n  \\"subheadline\\": \\"How we help our clients\\",\\n  \\"case_studies\\": [\\n    {\\"title\\": \\"Type of project or service area\\", \\"description\\": \\"What this involves and what clients can expect\\", \\"result\\": \\"The kind of outcomes typically achieved\\"},\\n    {\\"title\\": \\"Another service area\\", \\"description\\": \\"Description of approach\\", \\"result\\": \\"Typical outcomes\\"}\\n  ]\\n}\\n```\\n\\n## STRICT RULES:\\n1. Use the EXACT field names shown above (headline, subheadline, primary_cta, primary_cta_url, etc.)\\n2. No placeholder text like [Your Company] or Lorem ipsum\\n3. Write content that is relevant to this company's industry and services - but do NOT invent specific achievements, metrics, or outcomes that have not actually happened\\n4. Professional but engaging tone matching the brief\\n5. Include source citations [0], [1] if research was provided\\n6. NEVER invent contact information - use ONLY the email and phone provided in Official Contact Information above\\n7. For body text content, ALWAYS wrap paragraphs in <p> tags - never output raw unwrapped text\\n8. For \\"content\\" fields that contain multiple paragraphs, use proper HTML: <p>Paragraph 1</p><p>Paragraph 2</p>\\n9. If contact email or phone is empty in the brief, do NOT make one up - omit it or use a generic \\"Contact us\\" link\\n10. Only create internal links to pages listed in the Internal Linking section above\\n11. NEVER invent fake people, client names, or attributed quotes. No \\"Sarah Mitchell, Founder\\" or \\"James Chen, Marketing Director\\". If the brief does not include real testimonials, write company philosophy statements instead and leave name/title fields empty\\n12. NEVER invent specific statistics, percentages, or metrics. No \\"300% increase\\" or \\"47 minutes\\" or \\"42-page report\\". Describe the type of outcome without fabricating numbers\\n13. NEVER invent fake case studies with named businesses. No \\"Brighton Physiotherapy Clinic\\" or \\"Independent Mortgage Broker\\" as if they were real clients. Describe service categories and typical outcomes instead\\n14. For testimonial sections: write 2-3 statements in the company's own voice about their values, approach, or commitment. These serve as placeholder content the site owner will replace with real testimonials\\n15. For case study sections: describe the types of problems the company solves and the approach they take, without inventing specific clients or results\\n16. It is ALWAYS better to be honest and general than specific and fabricated. A real visitor will trust \\"We help businesses improve their online presence\\" far more than a fake testimonial from an invented person"}, "next_step": "render_section", "description": "Generate content for this section", "output_field": "generated_content"}, "check_render_mode": {"action": "conditional", "config": {"condition": "current_section.render_mode == 'agent' OR current_section.needs_llm == true", "else_step": "render_from_template", "then_step": "check_needs_research"}, "description": "Check if section needs LLM or just template"}, "check_needs_research": {"action": "conditional", "config": {"condition": "current_section.needs_research == true", "else_step": "generate_content", "then_step": "call_researcher"}, "description": "Check if section needs research first"}, "render_from_template": {"action": "render_component", "config": {"output_html": true, "content_from": "render_context", "context_from": "render_context", "component_from": "current_section"}, "description": "Render section from template with brief data only", "output_field": "section_output"}}, "start_step": "check_render_mode"}, "max_iterations": 15}, "next_step": "compile_page", "description": "Process each section - template render or LLM generate", "output_field": "processed_sections"}}, "start_step": "spawn_research_agent"}, "processing_mode": "task", "timeout_seconds": 180, "link_constraints": {"enabled": true, "max_internal_links_per_section": 3}}	t	2025-12-22 17:47:17.609605+00	2026-02-23 19:23:31.791914+00	\N	["content-generation", "template-rendering", "research"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	2	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	active	[]	{}	0	f	{"optional": ["reviewed_brief", "style_collection", "db_sync", "generated_images"], "required": ["current_page", "site_record"]}	{"produces": ["page_html", "metadata", "seo_data"]}
