d8c6adcc-7ce7-4b18-af1b-2f34db616c06	multipage-website-builder	Multi-Page Website Builder	Builds large websites (20+ pages) using batched generation to avoid token limits	orchestrator	{"workflow": {"steps": {"deploy": {"action": "call_agent", "config": {"agent_type": "deployer-agent", "target_role": "deployer", "input_mapping": {"input_data": "input_data", "site_files": "site_files", "site_record": "site_record"}, "timeout_seconds": 180}, "next_step": "update_timestamps", "description": "Deploy site to git repository", "output_field": "deployment_result"}, "complete": {"action": "complete_workflow", "description": "Multipage site build complete"}, "populate_nav": {"action": "populate_nav_tables", "config": {"input_fields": ["site_id"], "max_header_items": 8}, "next_step": "generate_pages_loop", "description": "Populate navigation tables from page records", "output_field": "nav_data"}, "assemble_site": {"action": "assemble_multipage_site", "config": {"pages_field": "all_pages", "add_navigation": true, "include_robots_txt": true, "include_sitemap_xml": true, "generate_standard_pages": true}, "next_step": "deploy", "description": "Assemble pages into complete site with navigation", "output_field": "site_files"}, "spawn_deployer": {"action": "spawn_agent", "config": {"role": "deployer", "agent_type": "deployer-agent"}, "next_step": "call_strategist", "description": "Spawn deployer agent", "output_field": "deployer_info"}, "call_strategist": {"action": "call_agent", "config": {"agent_type": "chief-strategist", "target_role": "strategist", "input_mapping": {"input_data": "input_data", "site_record": "site_record"}, "timeout_seconds": 120}, "next_step": "sync_pages_to_db", "description": "Get page plan from chief strategist", "output_field": "page_plan"}, "spawn_strategist": {"action": "spawn_agent", "config": {"role": "strategist", "agent_type": "chief-strategist"}, "next_step": "spawn_content_creator", "description": "Spawn chief strategist agent", "output_field": "strategist_info"}, "sync_pages_to_db": {"action": "sync_pages_to_db", "config": {"input_fields": ["site_record", "page_plan"]}, "next_step": "populate_nav", "description": "Sync pages to database and build navigation structure", "output_field": "db_sync"}, "update_timestamps": {"action": "update_site_timestamps", "config": {"input_fields": ["site_record"]}, "next_step": "complete", "description": "Update site last_built_at and last_deployed_at", "output_field": "timestamp_update"}, "ensure_site_record": {"action": "ensure_site_record", "config": {"input_fields": ["input_data"]}, "next_step": "spawn_strategist", "description": "Create or retrieve site record from database", "output_field": "site_record"}, "generate_pages_loop": {"action": "loop", "config": {"loop_var": "current_page", "substeps": {"create_html": {"action": "call_agent", "config": {"agent_type": "html-developer", "target_role": "developer", "input_mapping": {"db_sync": "db_sync", "page_plan": "page_plan", "input_data": "input_data", "current_page": "current_page", "page_content": "page_content"}, "timeout_seconds": 180}, "next_step": "extract_links", "description": "Convert content to professional HTML page", "output_field": "page_html"}, "extract_links": {"action": "extract_and_sync_links", "config": {"input_fields": ["page_html", "current_page", "site_record"]}, "description": "Extract links from HTML and sync to link registry", "output_field": "link_sync"}, "generate_content": {"action": "call_agent", "config": {"agent_type": "content-creator", "target_role": "writer", "input_mapping": {"page_plan": "page_plan", "input_data": "input_data", "current_page": "current_page"}, "timeout_seconds": 180}, "next_step": "create_html", "description": "Generate content strategy/copy for page", "output_field": "page_content"}}, "iterate_over": "page_plan.response.plan_data.pages", "max_iterations": 20}, "next_step": "assemble_site", "description": "Generate all pages with content and HTML conversion", "output_field":