2ed3b581-cdf7-4030-bb55-dbcfb5482270	section-editor	Section Editor Agent	Performs granular edits to individual page sections. Updates content_data (source of truth) then re-renders from template with full site context. Edits survive future re-renders.	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["edit_result", "git_result", "deploy_result"]}, "description": "Section edit complete"}, "apply_edit": {"action": "apply_section_edit", "config": {"input_fields": ["edit_type", "field_updates", "replacement_content_data", "new_component_function", "page_component_id"]}, "next_step": "deploy_page", "description": "Apply edit to content_data, re-render, reassemble page", "output_field": "edit_result"}, "deploy_page": {"action": "git_commit", "config": {"domain_field": "edit_result.domain", "content_field": "edit_result.html", "commit_message": "Section edit via section-editor", "filename_field": "edit_result.filename"}, "next_step": "update_page_status", "description": "Commit updated page HTML to git", "output_field": "git_result"}, "spawn_deployer": {"action": "spawn_agent", "config": {"role": "deployer", "agent_type": "deployer-agent"}, "next_step": "load_edit_context", "description": "Spawn deployer agent", "output_field": "deployer_agent"}, "trigger_deploy": {"action": "call_agent", "config": {"agent_type": "deployer-agent", "target_role": "deployer", "input_mapping": {"site_record": "site_record"}, "timeout_seconds": 120}, "next_step": "complete", "description": "Trigger Cloudflare deployment", "output_field": "deploy_result"}, "load_edit_context": {"action": "load_edit_context", "config": {"input_fields": ["site_id", "page_component_id", "page_name", "slot_name", "domain"]}, "next_step": "apply_edit", "description": "Load page component, component template, and page info", "output_field": "edit_context"}, "ensure_site_record": {"action": "ensure_site_record", "config": {}, "next_step": "spawn_deployer", "des