d35a5612-c961-4b03-8f1d-e9e45801f874	vet-practice-verifier	Vet Practice Verifier	Verifies and enriches a single veterinary practice record by searching the web, scraping the practice website, and extracting structured data via LLM.	data-driven	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["business_record", "verification_result", "store_result"]}, "description": "Verification complete"}, "load_business": {"action": "load_business_record", "config": {"input_fields": ["business_id"], "include_prices": true, "include_vet_details": true}, "next_step": "search_practice", "description": "Load current business data from DB", "output_field": "business_record"}, "store_results": {"action": "store_business_verification", "config": {"input_fields": ["business_id", "verification_result", "task_id"]}, "next_step": "scan_discoveries", "description": "Write verified data back to the database", "output_field": "store_result"}, "scrape_website": {"action": "scrape_web", "config": {"max_pages": 3, "url_field": "business_record.business.website_url", "extract_mode": "text", "follow_links": ["fees", "prices", "about", "team", "contact", "services"], "fallback_url_field": "search_results.results.0.url"}, "next_step": "prepare_context", "description": "Scrape the practice website for details and prices", "output_field": "scraped_data"}, "prepare_context": {"action": "prepare_extraction_context", "config": {"max_snippets": 10, "scrape_field": "scraped_data", "search_field": "search_results", "max_content_length": 8000}, "next_step": "extract_and_reconcile", "description": "Format search results and scraped content for LLM extraction", "output_field": "extraction_context"}, "search_practice": {"action": "web_search", "config": {"num_results": 5, "query_template": "{{.business_record.business.name}} {{.business_record.business.postcode}} veterinary practice"}, "next_step": "scrape_website", "description": "Search for the practice website and online presence", "output_field": "search_results"}, "scan_discoveries": {"action": "scan_discovery_candidates", "config": {"input_fields": ["business_id", "search_results", "search_practice", "business_record"]}, "next_step": "complete", "description": "Scan search results for unknown vet practices", "output_field": "discovery_scan"}, "extract_and_reconcile": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["business_record", "extraction_context"], "prompt_template": "You are a data extraction specialist for UK veterinary practices.\\n\\nCURRENT RECORD:\\nName: {{.business_record.business.name}}\\nPostcode: {{.business_record.business.postcode}}\\nTown: {{.business_record.business.town}}\\nWebsite: {{.business_record.business.website_url}}\\nGroup: {{.business_record.business.group_name}}\\n\\nSCRAPED WEBSITE CONTENT:\\n{{.extraction_context.website_content}}\\n\\nSEARCH RESULTS:\\n{{.extraction_context.search_summary}}\\n\\nExtract and return a JSON object with these sections:\\n\\n1. business - updated/confirmed fields:\\n   - name, address_line1, address_line2, town, county, postcode\\n   - phone: string OR array of strings if multiple numbers found (e.g. [\\"028 9047 1361\\", \\"028 9065 1729\\"])\\n   - email: string OR array of strings if multiple emails found (e.g. [\\"info@example.com\\", \\"referrals@example.com\\"])\\n   - fax: string if found\\n   - website_url, group_name, business_type\\n\\n2. vet_details - practice-specific:\\n   - species_treated (array of strings)\\n   - emergency_service (boolean)\\n   - out_of_hours_provider (string or null)\\n   - accepting_new_clients (boolean or null if unknown)\\n   - accreditations (array)\\n   - num_vets, num_nurses (integers or null)\\n   - head_vet_name (string or null)\\n   - has_own_lab, has_imaging, has_surgical_suite (booleans or null)\\n   - parking_available, wheelchair_accessible (booleans or null)\\n\\n3. vet_staff - array of notable vets/staff:\\n   - name, role, specialty, qualifications (strings)\\n\\n4. prices - array of objects, each with:\\n   - service_category: one of consultation, vaccination, surgery, prescription, dental, diagnostic, other\\n   - service_name: the specific service\\n   - price_gbp: numeric price\\n   - price_qualifier: fixed, from, or approximately\\n\\n5. confidence_score - 0.0 to 1.0, how confident you are in the data quality\\n6. extraction_notes - brief notes on data quality, conflicts, missing data\\n\\nOnly include fields where you have actual data. Use null for unknown values. Do not invent or estimate prices.\\nReturn ALL phone numbers and email addresses you find - do not discard any.", "response_format": "json"}, "next_step": "store_results", "description": "LLM extracts structured data from scraped content and reconciles with existing record", "output_field": "verification_result"}}, "start_step": "load_business"}, "processing_mode": "orchestrator", "timeout_seconds": 300}	t	2026-02-06 13:01:26.014952+00	2026-02-23 19:23:31.791914+00	\N	["data-collection", "web-scraping", "veterinary", "verification"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "1Gi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	specialist	experimental	["veterinary", "business-intelligence", "data-collection"]	{}	0	f	{"optional": ["task_id"], "required": ["business_id"]}	{"produces": {"store_result": "object - what was written to DB", "business_record": "object - the loaded business data", "verification_result": "object - extracted and reconciled data"}}
