3901d4e2-dadd-4e9b-94cf-d5e2001b4acc	content-creator	Content Creator V2	Creates content for component-based pages (v2 - receives current_page object)	data-driven	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return content"}, "create_content": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "output_type": "json", "input_fields": ["input_data", "current_page", "page_plan"], "prompt_template": "You are a professional copywriter creating content for a website page.\\n\\nCONTEXT:\\nDomain: {{.input_data.domain}}\\nObjective: {{.input_data.objective}}\\nMarketing Model: {{.input_data.model}}\\n\\nPAGE TO CREATE:\\nName: {{.current_page.name}}\\nTitle: {{.current_page.title}}\\nPurpose: {{.current_page.purpose}}\\nComponents: {{.current_page.components}}\\n\\nCreate content for EACH component listed above.\\n\\nComponent guidelines:\\n- hero-*: headline (5-8 words), subheadline (15-25 words), cta_text\\n- services-*: items array with name, description, icon_suggestion\\n- features-*: items array with name, benefit, detail\\n- testimonials-*: items array with quote, name, title, company\\n- team-*: items array with name, role, bio\\n- pricing-*: tiers array with name, price, features, cta\\n- faq-*: items array with question, answer\\n- cta-*: headline, supporting_text, button_text\\n- contact-*: intro, email, phone, address\\n- about-*: paragraphs array, key_points\\n- footer-*: company_name, tagline, link_groups, copyright\\n\\nOUTPUT FORMAT (valid JSON):\\n{\\n  \\"page_name\\": \\"index\\",\\n  \\"hero\\": {\\"headline\\": \\"...\\", \\"subheadline\\": \\"...\\", \\"cta_text\\": \\"...\\", \\"cta_url\\": \\"#\\"},\\n  \\"sections\\": [\\n    {\\"type\\": \\"component-type\\", \\"content\\": {...}}\\n  ],\\n  \\"meta\\": {\\"page_title\\": \\"...\\", \\"meta_description\\": \\"...\\"},\\n  \\"footer\\": {\\"company_name\\": \\"...\\", \\"tagline\\": \\"...\\", \\"copyright\\": \\"...\\"}\\n}"}, "next_step": "complete", "description": "Create content for page components", "output_field": "content_result"}}, "start_step": "create_content"}, "processing_mode": "task", "timeout_seconds": 180}	t	2025-12-18 13:07:22.761389+00	2026-02-23 19:23:31.791914+00	\N	["content-generation", "writing", "copywriting", "seo", "memory-enabled", "style-adaptive"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "1000m", "memory": "2Gi"}, "requests": {"cpu": "200m", "memory": "512Mi"}}	{"dlq": "system.agent.content-creator.dlq", "errors": "system.agent.content-creator.errors", "requests": "system.agent.content-creator.requests", "responses": "system.agent.content-creator.responses"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	2	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	experimental	[]	{}	0	f	{"expects": {"current_page": "object with name, components"}, "required": ["input_data", "current_page"]}	{"format": {"type": "object", "properties": {"hero": "object", "sections": "array"}}, "produces": "page_content"}
411211f5-7da2-4320-8f6f-0194ea23848c	simple-content-writer-with-approval	Simple Content Writer with HITL Approval	Generates content for organisations and waits for human approval before completion	data-driven	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return approved content with metadata"}, "generate_draft": {"action": "execute_llm_prompt", "config": {"input_fields": ["input_data"], "prompt_template": "Write a brief, professional description for {{.input_data.business_name}}. Context: {{.input_data.business_description}}. Focus on how they help organisations with {{.input_data.business_type}}. Keep it to 3-4 sentences that capture the essence of their value proposition."}, "next_step": "await_human_approval", "description": "Generate initial content draft"}, "process_approval": {"action": "process_data", "config": {"input_fields": ["generate_draft", "await_human_approval"], "output_format": {"content": "{{.generate_draft.result}}", "approved_at": "{{.await_human_approval.timestamp}}", "approved_by": "{{.await_human_approval.approved_by}}", "approval_status": "{{.await_human_approval.approved}}", "approval_comments": "{{.await_human_approval.comments}}"}}, "next_step": "complete", "description": "Process approval response and prepare final output"}, "await_human_approval": {"action": "await_approval", "config": {"timeout_seconds": 300, "notification_data": {"type": "content_approval", "title": "Content Approval Required for {{.input_data.business_name}}", "metadata": {"business_name": "{{.input_data.business_name}}", "business_type": "{{.input_data.business_type}}"}, "description": "Please review and approve the generated organisational description", "content_field": "generate_draft"}, "include_generated_content": true}, "next_step": "process_approval", "description": "Wait for human approval of generated content"}}, "start_step": "generate_draft"}, "ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "api_key