0a58cf02-4a9e-4900-9c7e-207622f12247	content-reviewer	Content Reviewer	Reviews page content for quality, accuracy, and brand alignment. Supports HITL mode (human review with edits) and auto-eval mode (LLM review with auto-approve or flag).	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output": {"edits": "review_result.edits", "issues": "review_result.issues", "content": "review_result.content", "approved": "review_result.approved", "review_mode": "review_result.review_mode", "reviewed_at": "review_result.reviewed_at", "reviewed_by": "review_result.reviewed_by"}}}, "handle_rejection": {"action": "build_review_result", "config": {"approved": false, "page_status": "review_rejected", "review_mode": "hitl", "reviewer_field": "processed_response.responded_by", "rejection_reason_field": "processed_response.rejection_reason"}, "next_step": "mark_page_needs_attention", "description": "Handle rejection - page will be picked up by maintenance", "output_field": "review_result"}, "validate_content": {"action": "validate_page_content", "config": {"check_emails": true, "input_fields": ["page_content", "site_record"], "check_internal_links": true}, "next_step": "determine_review_mode", "description": "Check for broken links and incorrect contact info", "output_field": "validation_result"}, "auto_eval_content": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "max_tokens": 1500, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["current_page", "page_content", "reviewed_brief", "validation_result"], "output_format": "json", "prompt_template": "Review this page content for quality and accuracy.\\n\\n## Page\\nName: {{.current_page.name}}\\nTitle: {{.current_page.title}}\\n\\n## Company Brief\\nCompany: {{.reviewed_brief.company_name}}\\nIndustry: {{.reviewed_brief.industry}}\\nTone: {{.reviewed_brief.tone}}\\nServices: {{.reviewed_brief.services}}\\n\\n## Content to Review\\n{{if .page_content.sections}}{{range .page_content.sections}}\\n### Section: {{.component_name}}\\n{{.rendered_html}}\\n{{end}}{{else if .page_content.process_sections_loop_complete}}{{range .page_content.process_sections_loop_complete.results}}\\n### Section: {{.component_name}}\\n{{.rendered_html}}\\n{{end}}{{else if .page_content.processed_sections}}{{range .page_content.processed_sections.results}}\\n### Section: {{.component_name}}\\n{{.rendered_html}}\\n{{end}}{{else}}\\n### Full Page HTML\\n{{.page_content.compile_page.page_html}}\\n{{end}}\\n\\n## Evaluation Criteria\\n1. Accuracy: Does content match the brief? No invented claims?\\n2. Completeness: Are all sections filled in properly?\\n3. Quality: Professional tone? No placeholder text?\\n4. Brand Alignment: Matches company voice and values?\\n5. Technical: Valid HTML? Proper structure?\\n\\n## Return JSON:\\n```json\\n{\\n  \\"approved\\": true/false,\\n  \\"overall_score\\": 0.0-1.0,\\n  \\"issues\\": [\\n    {\\n      \\"section\\": \\"hero\\",\\n      \\"severity\\": \\"error|warning|info\\",\\n      \\"issue\\": \\"Description of the issue\\",\\n      \\"suggestion\\": \\"How to fix it\\"\\n    }\\n  ],\\n  \\"strengths\\": [\\"Good point 1\\", \\"Good point 2\\"],\\n  \\"summary\\": \\"Brief overall assessment\\"\\n}\\n```\\n\\nApprove if:\\n- No errors (warnings are OK)\\n- Score >= 0.7\\n- No placeholder text detected\\n- Content matches brief"}, "next_step": "check_auto_approval", "description": "LLM evaluates content quality and accuracy", "output_field": "eval_result"}, "complete_rejected": {"action": "complete_workflow", "config": {"status": "rejected", "output_fields": ["review_result", "validation_result"], "continue_parent": true}, "description": "Complete with rejection - parent workflow continues with next page"}, "escalate_to_human": {"action": "request_human_input", "config": {"message": "Content needs review for {{current_page.name}}", "editable": true, "ui_config": {"title": "Content Review Required", "actions": ["approve", "approve_with_edits", "reject"], "description": "Auto-evaluation flagged issues. Please review.", "allow_html_edit": true, "show_validation_issues": true}, "show_issues": true, "request_type": "review", "editable_field": "page_content.response.page_html", "timeout_seconds": 3600, "eval_issues_field": "eval_result.issues", "notification_topic": "system.notifications.ui", "validation_issues_field": "validation_result.issues"}, "next_step": "process_human_response", "description": "Escalate to human - auto-eval found issues", "output_field": "human_response"}, "check_auto_approval": {"action": "conditional", "config": {"condition": "eval_result.approved == true AND eval_result.overall_score >= 0.7 AND (validation_result.error_count == 0 OR validation_result.error_count == null)", "else_step": "escalate_to_human", "then_step": "finalize_auto_result"}, "description": "Check if auto-eval passed or needs human review"}, "check_hitl_approved": {"action": "conditional", "config": {"condition": "processed_response.approved == true", "else_step": "handle_rejection", "then_step": "finalize_hitl_result"}, "description": "Check if human approved or rejected"}, "prepare_hitl_review": {"action": "prepare_review_data", "config": {"html_field": "page_content.response.page_html", "issues_field": "validation_result.issues", "include_fields": ["current_page", "page_content", "reviewed_brief", "validation_result"], "highlight_issues": true, "format_for_display": true}, "next_step": "request_human_review", "description": "Prepare content for human review with issues highlighted", "output_field": "review_data"}, "finalize_auto_result": {"action": "build_review_result", "config": {"approved": true, "reviewer": "eval-agent", "eval_score": "eval_result.overall_score", "review_mode": "auto-eval"}, "next_step": "update_component_status", "description": "Build result from successful auto-eval", "output_field": "review_result"}, "finalize_hitl_result": {"action": "build_review_result", "config": {"approved": true, "edits_field": "processed_response.edits", "review_mode": "hitl", "approved_field": "processed_response.approved", "reviewer_field": "processed_response.responded_by", "edited_html_field": "processed_response.edited_content", "original_html_field": "page_content.response.page_html", "use_edited_if_present": true}, "next_step": "update_component_status", "description": "Build result using edited content if provided", "output_field": "review_result"}, "request_human_review": {"action": "request_human_input", "config": {"message": "Review page content for {{current_page.name}}", "editable": true, "ui_config": {"title": "Content Review", "actions": ["approve", "approve_with_edits", "reject"], "show_diff": true, "description": "Review and edit page content before publishing", "issues_field": "validation_result.issues", "allow_comments": true, "allow_html_edit": true, "show_validation_issues": true}, "request_type": "review", "editable_field": "review_data.html", "stop_on_cancel": false, "timeout_seconds": 3600, "notification_topic": "system.notifications.ui"}, "next_step": "process_human_response", "description": "Send to HITL for human review - can edit HTML to fix issues", "output_field": "human_response"}, "determine_review_mode": {"action": "conditional", "config": {"condition": "(input_data.review_mode == 'hitl' OR review_mode == 'hitl') OR (input_data.require_human_review == true OR require_human_review == true)", "else_step": "auto_eval_content", "then_step": "prepare_hitl_review"}, "description": "Check whether to use HITL or auto-eval"}, "process_human_response": {"action": "process_human_input_response", "config": {"extract_edits": true, "approval_field": "approved", "edited_html_field": "edited_content", "rejection_reason_field": "rejection_reason"}, "next_step": "check_hitl_approved", "description": "Process human response - extract any HTML edits", "output_field": "processed_response"}, "update_component_status": {"action": "update_page_components_status", "config": {"status": "approved", "page_from": "current_page", "reviewed_at_field": "review_result.reviewed_at", "reviewed_by_field": "review_result.reviewed_by"}, "next_step": "complete", "description": "Update page_components build_status and review info", "output_field": "status_updated"}, "mark_page_needs_attention": {"action": "update_page_status", "config": {"status": "needs_attention", "notes_field": "processed_response.rejection_reason", "page_id_field": "input_data.current_page.id", "validation_issues_field": "validation_result.issues"}, "next_step": "complete_rejected", "description": "Mark page for maintenance workflow to handle", "output_field": "page_status_updated"}, "finalize_escalation_result": {"action": "build_review_result", "config": {"review_mode": "escalated", "auto_eval_issues": "eval_result.issues"}, "next_step": "update_component_status", "description": "Build result from escalated HITL review", "output_field": "review_result"}, "process_escalation_response": {"action": "process_human_input_response", "config": {"extract_edits": true}, "next_step": "finalize_escalation_result", "description": "Process response from escalated review", "output_field": "escalation_processed"}}, "start_step": "validate_content"}, "processing_mode": "task", "timeout_seconds": 600}	t	2025-12-22 17:47:42.958031+00	2026-02-23 19:23:31.791914+00	\N	["content-review", "quality-assurance", "hitl", "auto-eval"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	5	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	active	[]	{}	0	f	{"optional": ["reviewed_brief"], "required": ["current_page", "page_content"]}	{"produces": ["review_result", "approved", "feedback"]}
5b3be002-256f-4f1f-88cf-446083a1738f	chief-strategist	Chief Strategist V2	Site planner that outputs pages with component types (v2 - unified architecture)	data-driven	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return parsed plan"}, "parse_plan": {"action": "parse_json_field", "config": {"source_field": "build_plan_raw"}, "next_step": "complete", "description": "Parse JSON plan", "output_field": "plan_data"}, "generate_build_plan": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "output_type": "json", "input_fields": ["input_data"], "prompt_template": "You are a Site Planner designing the structure for {{.input_data.domain}}.\\n\\nOBJECTIVE: {{.input_data.objective}}\\nMARKETING MODEL: {{.input_data.model}}\\n\\nSTEP 1: Determine the best site type for this objective.\\n\\nSite Type Guidelines:\\n\\nLANDING (1 page, 5-8 components)\\n- Product launches, lead generation, focused campaigns\\n- Single conversion goal, minimal navigation\\n- Revenue: Direct sales, lead capture\\n\\nCORPORATE (4-6 pages)\\n- Professional services, consulting, established businesses\\n- Trust-building, multiple service areas\\n- Revenue: Service contracts, B2B relationships\\n\\nPORTFOLIO (3-5 pages)\\n- Creatives, agencies, freelancers\\n- Case study focused, visual showcase\\n- Revenue: Project work, client acquisition\\n\\nECOMMERCE (2-4 pages + product structure)\\n- Product sales, shopping focused\\n- Category browsing, cart functionality\\n- Revenue: Direct product sales\\n\\nCONTENT (4-8 pages + article structure)\\n- News sites, blogs, recipes, celebrity gossip, lifestyle\\n- Content-driven traffic, regular publishing\\n- SEO focused, high page count potential\\n- Revenue: Advertising, affiliate links, sponsored content\\n\\nTOOLS (2-5 pages + tool interfaces)\\n- Calculators (mortgage, tiles, BMI, etc.), converters, utilities\\n- Feature/functionality driven, practical value\\n- User retention through bookmarking\\n- Revenue: Advertising, affiliate referrals, premium features\\n\\nSTEP 2: Plan each page with specific components.\\n\\nAvailable component types:\\n- hero-centered, hero-split, hero-video\\n- services-grid, services-list\\n- features-cards, features-comparison\\n- testimonials-carousel, testimonials-grid\\n- team-grid, pricing-tiers, faq-accordion\\n- cta-banner, cta-split\\n- contact-form, contact-simple\\n- about-story, about-values\\n- footer-standard\\n- blog-grid, blog-featured, article-layout\\n- recipe-card, recipe-grid, recipe-detail\\n- tool-calculator, tool-converter, tool-interface\\n- ad-banner, ad-sidebar, affiliate-showcase\\n- category-grid, content-feed, search-bar\\n- social-share, comments-section, newsletter-signup\\n\\nSTEP 3: Create the sitemap with navigation structure.\\n\\nThe sitemap defines:\\n- How each page appears in navigation\\n- The URL for each page\\n- Whether it appears in header nav, footer nav, or both\\n\\nURL Rules:\\n- Home page: /index.html\\n- Other pages: /{page-name}.html (e.g., /about.html, /services.html)\\n- Use lowercase, hyphens for multi-word names\\n\\nOUTPUT FORMAT (valid JSON only):\\n{\\n  \\"site_type\\": \\"landing|corporate|portfolio|ecommerce|content|tools\\",\\n  \\"reasoning\\": \\"Why this structure fits the objective\\",\\n  \\"theme_suggestion\\": \\"professional|bold|minimal|creative|editorial|functional\\",\\n  \\"revenue_model\\": \\"direct_sales|services|advertising|affiliate|freemium\\",\\n  \\"pages\\": [\\n    {\\n      \\"name\\": \\"index\\",\\n      \\"title\\": \\"Page Title | Brand\\",\\n      \\"purpose\\": \\"What this page achieves\\",\\n      \\"components\\": [\\n        {\\"type\\": \\"hero-centered\\", \\"priority\\": \\"high\\"},\\n        {\\"type\\": \\"services-grid\\", \\"priority\\": \\"high\\"}\\n      ],\\n      \\"meta_description\\": \\"SEO description\\"\\n    }\\n  ],\\n  \\"sitemap\\": [\\n    {\\"label\\": \\"Home\\", \\"page\\": \\"index\\", \\"url\\": \\"/index.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"About\\", \\"page\\": \\"about\\", \\"url\\": \\"/about.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Services\\", \\"page\\": \\"services\\", \\"url\\": \\"/services.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Contact\\", \\"page\\": \\"contact\\", \\"url\\": \\"/contact.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Privacy Policy\\", \\"page\\": \\"privacy\\", \\"url\\": \\"/privacy.html\\", \\"in_header\\": false, \\"in_footer\\": true}\\n  ],\\n  \\"global\\": {\\n    \\"brand_tone\\": \\"professional|friendly|bold|technical|editorial|practical\\",\\n    \\"primary_cta\\": {\\"text\\": \\"Get Started\\", \\"url\\": \\"/contact.html\\"}\\n  }\\n}\\n\\nIMPORTANT:\\n- Every page in \\"pages\\" array MUST have a corresponding entry in \\"sitemap\\"\\n- The \\"page\\" field in sitemap MUST match the \\"name\\" field in pages\\n- Home page is always /index.html\\n- Include privacy/terms pages in footer only (in_header: false)\\n\\nEXAMPLE - Corporate site:\\n{\\n  \\"site_type\\": \\"corporate\\",\\n  \\"pages\\": [\\n    {\\"name\\": \\"index\\", \\"title\\": \\"Home | Acme Corp\\", \\"components\\": [{\\"type\\": \\"hero-centered\\"}, {\\"type\\": \\"services-grid\\"}, {\\"type\\": \\"testimonials-carousel\\"}, {\\"type\\": \\"cta-banner\\"}]},\\n    {\\"name\\": \\"about\\", \\"title\\": \\"About Us | Acme Corp\\", \\"components\\": [{\\"type\\": \\"about-story\\"}, {\\"type\\": \\"team-grid\\"}, {\\"type\\": \\"about-values\\"}]},\\n    {\\"name\\": \\"services\\", \\"title\\": \\"Our Services | Acme Corp\\", \\"components\\": [{\\"type\\": \\"hero-split\\"}, {\\"type\\": \\"services-list\\"}, {\\"type\\": \\"faq-accordion\\"}]},\\n    {\\"name\\": \\"contact\\", \\"title\\": \\"Contact Us | Acme Corp\\", \\"components\\": [{\\"type\\": \\"contact-form\\"}, {\\"type\\": \\"cta-split\\"}]}\\n  ],\\n  \\"sitemap\\": [\\n    {\\"label\\": \\"Home\\", \\"page\\": \\"index\\", \\"url\\": \\"/index.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"About Us\\", \\"page\\": \\"about\\", \\"url\\": \\"/about.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Services\\", \\"page\\": \\"services\\", \\"url\\": \\"/services.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Contact\\", \\"page\\": \\"contact\\", \\"url\\": \\"/contact.html\\", \\"in_header\\": true, \\"in_footer\\": true},\\n    {\\"label\\": \\"Privacy Policy\\", \\"page\\": \\"privacy\\", \\"url\\": \\"/privacy.html\\", \\"in_header\\": false, \\"in_footer\\": true}\\n  ],\\n  \\"global\\": {\\n    \\"brand_tone\\": \\"professional\\",\\n    \\"primary_cta\\": {\\"text\\": \\"Get in Touch\\", \\"url\\": \\"/contact.html\\"}\\n  }\\n}"}, "next_step": "parse_plan", "description": "Generate site plan with pages and components", "output_field": "build_plan_raw"}}, "start_step": "generate_build_plan"}, "processing_mode": "task", "timeout_seconds": 120}	t	2025-11-19 13:49:41.175751+00	2026-02-23 19:23:31.791914+00	\N	["strategy"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "1Gi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	2	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	strategist	active	["website"]	{}	0	f	{"expects": {"input_data.domain": "string", "input_data.objective": "string"}, "required": ["input_data"]}	{"format": {"type": "object", "properties": {"pages": "array", "site_type": "string"}}, "produces": "plan_data"}
2cb37e59-6e08-43c6-b356-495d9b784aca	research-agent	Research Agent	Researches topics via web search, extracts relevant quotes, synthesizes findings with full source attribution. Stores results in research_results table for citation.	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output": {"id": "stored_research.id", "query": "search_query.result", "summary": "synthesis.result.summary", "confidence": "synthesis.result.confidence", "key_points": "synthesis.result.key_points", "source_count": "research_content.source_count", "content_quality": "research_content.content_quality", "recommendations": "synthesis.result.recommendations"}}, "description": "Complete research workflow and return results"}, "search_web": {"action": "web_search", "config": {"query_from": "search_query.result", "num_results": 10}, "next_step": "prepare_urls", "description": "Search the web for relevant sources", "output_field": "search_results"}, "synthesize": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "max_tokens": 1500, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["extracted", "research_content"], "output_format": "json", "prompt_template": "Synthesize research findings about: {{.extracted.topic}}\\n\\n{{.research_content.research_text}}\\n\\n## Task\\nWrite a comprehensive synthesis of the findings. Cite sources by index [0], [1], [2] where applicable.\\n\\nReturn JSON:\\n{\\n  \\"summary\\": \\"3-4 paragraph synthesis with [citations] where relevant\\",\\n  \\"key_points\\": [\\"key point with [citation]\\", \\"another point [citation]\\"],\\n  \\"recommendations\\": [\\"actionable recommendation based on findings\\"],\\n  \\"confidence\\": 0.0-1.0\\n}\\n\\nRules:\\n- Cite sources when making specific claims\\n- Be factual and objective\\n- Note any conflicting information between sources\\n- Rate confidence based on source quality and agreement"}, "next_step": "store_research", "description": "Synthesize findings into comprehensive summary with citations", "output_field": "synthesis"}, "prepare_urls": {"action": "prepare_urls", "config": {"max_scrapes": 3, "max_snippets": 5, "prefer_domains": [".gov", ".edu", ".org", "reuters.com", "bbc.com", "forbes.com", "hbr.org", "mckinsey.com"], "exclude_domains": ["pinterest.com", "facebook.com", "twitter.com", "instagram.com", "youtube.com", "reddit.com"]}, "next_step": "scrape_pages", "description": "Extract top URLs for scraping and collect snippets", "output_field": "prepared_urls"}, "scrape_pages": {"action": "batch_webscrape", "config": {"urls_field": "prepared_urls.urls_to_scrape", "scrape_config": {"only_main_content": true, "capture_screenshot": false}}, "next_step": "format_content", "description": "Scrape top result pages for detailed content", "output_field": "scrape_results", "timeout_seconds": 60}, "extract_topic": {"action": "extract_fields", "config": {"fields": {"topic": ["current_section.topic", "current_section.research_query", "current_section.name"], "company": ["reviewed_brief.company_name"], "industry": ["reviewed_brief.industry", "reviewed_brief.category"]}}, "next_step": "build_search_query", "description": "Extract research topic from section data", "output_field": "extracted"}, "format_content": {"action": "format_research_content", "config": {"scrape_field": "scrape_results", "snippets_field": "prepared_urls.snippet_context", "max_content_per_source": 6000}, "next_step": "synthesize", "description": "Format scraped content and snippets for synthesis", "output_field": "research_content"}, "store_research": {"action": "insert_research_result", "config": {"table": "research_results", "fields": {"query": "search_query.result", "topic": "extracted.topic", "site_id": "site_record.site_id", "sources": "research_content.sources", "summary": "synthesis.result", "findings": "synthesis.result"}}, "next_step": "complete", "description": "Store research in database for future reference", "output_field": "stored_research"}, "build_search_query": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5", "provider": "anthropic", "max_tokens": 150, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["extracted"], "prompt_template": "Create a focused web search query to research:\\n\\nTopic: {{.extracted.topic}}\\nIndustry: {{.extracted.industry}}\\nCompany: {{.extracted.company}}\\n\\nReturn ONLY the search query string, 3-8 words, no quotes or operators.\\nFocus on finding authoritative, recent information about this topic."}, "next_step": "search_web", "description": "Build effective search query from context", "output_field": "search_query"}}, "start_step": "extract_topic"}, "processing_mode": "task", "timeout_seconds": 180}	t	2025-12-22 17:47:31.543928+00	2026-02-23 19:23:31.791914+00	\N	["web-search", "research", "citation", "synthesis"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	active	[]	{}	0	f	{"optional": ["site_record", "page", "domain"], "required": ["research_request"]}	{"produces": ["research_results", "products", "competitor_data"]}
a1d7b106-5c8b-4f44-b181-cd739c8e0c33	site-scraper	Site Scraper Agent	Scrapes live websites to extract design context. Uses webscrape adapter with Firecrawl. Outputs site_context for webdesign-agent.	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["site_context", "scrape_result"]}}, "scrape_site": {"action": "firecrawl_scrape", "config": {"url_field": "input_data.url", "scrape_config": {"only_main_content": false, "capture_screenshot": false}, "upload_results": false}, "next_step": "analyze_design", "description": "Scrape the website homepage", "output_field": "scrape_result"}, "analyze_design": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-5", "provider": "anthropic", "max_tokens": 3000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["scrape_result", "input_data"], "output_format": "json", "prompt_template": "Analyze this scraped website data and extract design information.\\n\\nTarget URL: {{.input_data.url}}\\n\\nScrape Result:\\n{{.scrape_result}}\\n\\nExtract from the scraped content:\\n1. Colors - hex/rgb colors from CSS or inline styles\\n2. Fonts - font-family declarations\\n3. Components - section types (hero, features, testimonials, cta, etc.)\\n4. Navigation pages from links\\n5. Company name and tagline\\n\\nReturn ONLY valid JSON:\\n{\\n  \\"domain\\": \\"domain from url\\",\\n  \\"company_name\\": \\"extracted name\\",\\n  \\"tagline\\": \\"tagline or null\\",\\n  \\"industry\\": \\"inferred industry\\",\\n  \\"color_palette\\": {\\"primary\\": \\"#hex\\", \\"secondary\\": \\"#hex\\", \\"accent\\": \\"#hex\\", \\"background\\": \\"#fff\\", \\"text\\": \\"#333\\"},\\n  \\"typography\\": {\\"font_family\\": \\"fonts\\", \\"heading_font\\": \\"heading font\\", \\"base_size\\": \\"16px\\", \\"line_height\\": \\"1.6\\"},\\n  \\"all_component_functions\\": [\\"hero\\", \\"features\\", \\"cta\\"],\\n  \\"pages\\": [{\\"title\\": \\"Home\\", \\"slug\\": \\"/\\"}],\\n  \\"source\\": \\"scrape\\",\\n  \\"design_notes\\": \\"brief notes\\"\\n}"}, "next_step": "complete", "description": "Analyze scraped content for design elements", "output_field": "site_context"}}, "start_step": "scrape_site"}, "processing_mode": "task", "timeout_seconds": 180}	t	2026-01-29 15:44:05.722503+00	2026-02-23 19:23:31.791914+00	\N	["scraper", "design", "analysis", "specialist"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "1Gi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	\N	experimental	[]	{}	0	f	{"optional": ["provider"], "required": ["url"]}	{"produces": {"site_context": "standardized site context for webdesign-agent"}}
