1c753364-1fec-4c91-b46f-89647424818c	rerender-site	Rerender Site	Re-renders and deploys all pages for a site from stored components. Re-renders site-level components (header, footer, head), then spawns page-rerender agent for each page. Used after design changes, component updates, or nav changes.	orchestrator	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["site_record", "site_components_rendered", "pages_rerendered", "deployment_result"]}, "description": "Rerender complete"}, "get_pages": {"action": "get_pages_for_rerender", "config": {"include_statuses": ["deployed", "active"]}, "next_step": "rerender_loop", "description": "Get all deployed pages for reassembly", "output_field": "pages_for_rerender"}, "rerender_loop": {"action": "loop", "config": {"mode": "sequential", "items_field": "pages_for_rerender.pages", "sub_workflow": {"steps": {"call_rerender": {"action": "call_agent", "config": {"agent_type": "page-rerender", "target_role": "rerenderer", "input_mapping": {"domain": "site_record.domain", "page_id": "current_page.page_id", "site_id": "site_record.site_id"}, "timeout_seconds": 120}, "next_step": "complete_page", "description": "Spawn page-rerender for this page", "output_field": "page_result"}, "complete_page": {"action": "loop_complete", "description": "Page rerender iteration complete"}}, "start_step": "call_rerender"}, "item_variable": "current_page", "max_iterations": 50}, "next_step": "trigger_deploy", "description": "Rerender each page via page-rerender agent", "output_field": "pages_rerendered"}, "spawn_deployer": {"action": "spawn_agent", "config": {"role": "deployer", "agent_type": "deployer-agent"}, "next_step": "spawn_rerenderer", "description": "Spawn deployer for final Cloudflare push", "output_field": "deployer_agent"}, "trigger_deploy": {"action": "call_agent", "config": {"agent_type": "deployer-agent", "target_role": "deployer", "input_mapping": {"pages_built": "pages_rerendered", "site_reco