e9a9bac9-dfe4-4aca-8f32-19738ac265c6	asset-deployer	Asset Deployer	Deploys a single image asset: downloads from S3, optimizes by purpose, commits to git. Reusable for any image deploy task.	specialist	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["deploy_result"]}, "description": "Asset deploy complete"}, "deploy_asset": {"action": "deploy_image_asset", "config": {"input_fields": ["s3_uri", "deploy_path", "purpose", "domain"]}, "next_step": "complete", "description": "Download from S3, optimize by purpose, commit to git", "output_field": "deploy_result"}}, "start_step": "deploy_asset"}, "processing_mode": "orchestrator", "timeout_seconds": 120}	t	2026-02-20 16:26:24.455968+00	2026-02-23 19:23:31.791914+00	\N	["image-deploy", "asset-management"]	docker.io/aqls/agent-chassis	v1.0.803	\N	{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "128Mi"}}	{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}	{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}	[]	1	\N	\N	\N	\N	{"fallback_to_self": true, "prefer_delegation": true}	specialist	experimental	["image", "deploy", "asset", "git"]	{}	0	f	{"optional": ["deploy_path", "purpose"], "required": ["domain", "s3_uri"], "description": "Provide domain + s3_uri. Optional deploy_path overrides default path. Optional purpose (default: hero) controls resize dimensions."}	{"produces": {"deploy_result": "Git commit result with image_url, output_path, size_bytes"}}
