427aa3e5-5ea2-4917-8d24-d751ebd283b2	pageflow-builder	PageFlow Builder	Component-based website builder. Spawns specialist agents (planner, content writer, reviewer, deployer), uses DB components for structure, LLM only for content. Builds and deploys pages one at a time.	orchestrator	{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["site_record", "pages_built", "deployment_result"]}, "description": "Site build complete"}, "populate_nav": {"action": "populate_nav_tables", "config": {"input_fields": ["site_id"], "max_header_items": 8}, "next_step": "check_assets_needed", "description": "Populate navigation tables from page records", "output_field": "nav_data"}, "generate_logo": {"action": "conditional", "config": {"condition": "site_plan.needs_logo == true", "else_step": "check_hero_images", "then_step": "call_logo_generation"}, "description": "Check if logo needs to be generated"}, "spawn_planner": {"action": "spawn_agent", "config": {"role": "planner", "agent_type": "site-planner"}, "next_step": "spawn_content_writer", "description": "Spawn site planner agent", "output_field": "planner_agent"}, "spawn_deployer": {"action": "spawn_agent", "config": {"role": "deployer", "agent_type": "deployer-agent"}, "next_step": "ensure_site_record", "description": "Spawn deployer agent", "output_field": "deployer_agent"}, "spawn_reviewer": {"action": "spawn_agent", "config": {"role": "reviewer", "agent_type": "content-reviewer"}, "next_step": "spawn_deployer", "description": "Spawn content reviewer agent", "output_field": "reviewer_agent"}, "store_site_plan": {"action": "update_site_content", "config": {"merge": true, "content_field": "site_plan", "site_id_field": "site_record.site_id"}, "next_step": "sync_pages_to_db", "description": "Store the site plan in sites.content_data", "output_field": "content_stored"}, "build_pages_loop": {"action": "loop", "config": {"mode": "sequential", "items_field": "pages_to_build.pages", "sub_workflow": {"steps": {"deploy_page": {"action": "git_commit", "config": {"page_field": "current_page", "domain_field": "site_record.domain", "content_field": "assembled_page.html"}, "next_step": "save_sections", "description": "Commit page to git", "output_field": "page_deployed"}, "assemble_page": {"action": "assemble_page", "config": {"inject_head": false, "content_field": "page_content.response.page_html", "add_navigation": false}, "next_step": "deploy_page", "description": "Assemble full page HTML from components", "output_field": "assembled_page"}, "complete_page": {"action": "loop_complete", "description": "Page build complete"}, "save_sections": {"action": "save_page_sections", "config": {"html_field": "assembled_page.html", "site_id_field": "site_record.site_id", "page_name_field": "current_page.name"}, "next_step": "update_page_status", "description": "Save rendered sections to page_components for rerender", "output_field": "save_result"}, "update_page_status": {"action": "update_page_status", "config": {"status": "deployed", "commit_from": "page_deployed.commit_sha", "page_id_field": "current_page.id"}, "next_step": "complete_page", "description": "Mark page as deployed in database"}, "write_page_content": {"action": "call_agent", "config": {"agent_type": "page-content-writer", "target_role": "content_writer", "input_mapping": {"db_sync": "db_sync", "hero_url?": "hero_url", "logo_url?": "logo_url", "site_plan": "site_plan", "site_record": "site_record", "current_page": "current_page", "reviewed_brief": "input_data.reviewed_brief", "brand_logo_url?": "brand_logo_url", "style_collection": "style_collection"}, "timeout_seconds": 300}, "next_step": "review_page_content", "description": "Write content for this page", "output_field": "page_content"}, "review_page_content": {"action": "call_agent", "config": {"agent_type": "content-reviewer", "target_role": "reviewer", "input_mapping": {"site_record": "site_record", "current_page": "current_page", "page_content": "page_content", "reviewed_brief": "input_data.reviewed_brief"}, "timeout_seconds": 3900}, "next_step": "check_review_approved", "description": "Review page content (HITL or auto-eval)", "output_field": "reviewed_content"}, "check_review_approved": {"action": "conditional", "config": {"condition": "reviewed_content.review_result.approved == true OR reviewed_content.approved == true", "else_step": "complete_page", "then_step": "assemble_page"}, "description": "Check if content was approved - skip deploy if rejected"}}, "start_step": "write_page_content"}, "item_variable": "current_page", "max_iterations": 20}, "next_step": "apply_site_design", "description": "Build each page: write → review → deploy", "output_field": "pages_built"}, "store_hero_asset": {"action": "store_asset", "config": {"purpose": "hero", "asset_type": "image", "data_field": "hero_result.image_url", "origin_type": "generated", "site_id_field": "site_record.site_id", "brand_asset_key": "hero_images.home", "origin_prompt_field": "site_plan.image_prompts.hero_home", "update_site_brand_assets": true}, "next_step": "deploy_hero_image", "description": "Store generated hero image", "output_field": "hero_stored"}, "store_logo_asset": {"action": "store_asset", "config": {"purpose": "logo", "asset_type": "logo", "data_field": "logo_result.image_url", "origin_type": "generated", "site_id_field": "site_record.site_id", "brand_asset_key": "logo.primary", "origin_prompt_field": "site_plan.image_prompts.logo", "update_site_brand_assets": true}, "next_step": "deploy_logo_image", "description": "Store generated logo in assets table and site brand_assets", "output_field": "logo_stored"}, "sync_pages_to_db": {"action": "sync_pages_to_db", "config": {"input_fields": ["site_record", "site_plan"]}, "next_step": "populate_nav", "description": "Create page records from site plan", "output_field": "db_sync"}, "apply_site_design": {"action": "call_agent", "config": {"agent_type": "webdesign-agent", "target_role": "webdesigner", "