--
-- Name: agent_definitions agent_definitions_pkey; Type: CONSTRAINT; Schema: public; Owner: clients_user
--

ALTER TABLE ONLY public.agent_definitions
    ADD CONSTRAINT agent_definitions_pkey PRIMARY KEY (id);


--
-- Name: agent_definitions agent_definitions_type_version_key; Type: CONSTRAINT; Schema: public; Owner: clients_user
--

ALTER TABLE ONLY public.agent_definitions
    ADD CONSTRAINT agent_definitions_type_version_key UNIQUE (type, version);


--
-- Name: idx_ad_category; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_ad_category ON public.agent_definitions USING btree (agent_category);


--
-- Name: idx_ad_domain_tags; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_ad_domain_tags ON public.agent_definitions USING gin (domain_tags);


--
-- Name: idx_ad_status; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_ad_status ON public.agent_definitions USING btree (status);


--
-- Name: idx_agent_definitions_category; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_agent_definitions_category ON public.agent_definitions USING btree (category) WHERE (is_active = true);


--
-- Name: idx_agent_definitions_type_active; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_agent_definitions_type_active ON public.agent_definitions USING btree (type, is_active) WHERE (deleted_at IS NULL);


--
-- Name: idx_agent_definitions_type_version; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_agent_definitions_type_version ON public.agent_definitions USING btree (type, version DESC);


--
-- Name: idx_agent_definitions_usage; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_agent_definitions_usage ON public.agent_definitions USING btree (usage_count DESC) WHERE (is_active = true);


--
-- Name: idx_agent_definitions_version; Type: INDEX; Schema: public; Owner: clients_user
--

CREATE INDEX idx_agent_definitions_version ON public.agent_definitions USING btree (type, version);


--
-- Name: agent_definitions agent_definitions_previous_version_id_fkey; Type: FK CONSTRAINT; Schema: public; Owner: clients_user
--

ALTER TABLE ONLY public.agent_definitions
    ADD CONSTRAINT agent_definitions_previous_version_id_fkey FOREIGN KEY (previous_version_id) REFERENCES public.agent_definitions(id);


